record.field:
for activity in records:
    picking = env['stock.picking'].browse(activity.res_id).exists()
    # Bypass nếu Picking đã hoàn tất
    if picking and picking.state == 'done':
        continue

    if picking and picking.state in ['assigned']:
        missing_lot_move = env['stock.move'].search([
            ('picking_id', '=', picking.id),
            ('product_id.tracking', 'in', ['lot', 'serial']),
            ('move_line_ids', 'any', [
                ('quantity', '>', 0),
                ('lot_id', '=', False),
                ('lot_name', '=', False),
            ]),
        ], limit=1)

        if missing_lot_move:
            if picking.picking_type_id.code == 'incoming':
                env.ref(
                    'fmcg_business_automation.action_create_incoming_lot_serial'
                ).with_context(
                    active_model='stock.picking',
                    active_id=picking.id,
                    active_ids=picking.ids,
                    old_values=None,
                    domain_post=None,
                ).run()
            else:
                picking.activity_schedule(
                    'fmcg_business_automation.mail_activity_type_picking_existing_lot_serial',
                    date_deadline=activity.date_deadline,
                    user_id=activity.user_id.id,
                    summary='Tự động điền Lot/Serial đang có trong kho',
                    note=(
                        'Phiếu kho %s thiếu Lot/Serial khi Validate. '
                        'Vui lòng hoàn tất Activity để tự động điền Lot/Serial '
                        'đang có trong kho.' % picking.name
                    ),
                )

                continue

        result = picking.button_validate()

        is_backorder_wizard = (
            isinstance(result, dict)
            and result.get('res_model') == 'stock.backorder.confirmation'
        )

        if is_backorder_wizard:
            backorder_activity_type = env.ref(
                'fmcg_business_automation.mail_activity_type_picking_backorder_required'
            )

            existing_backorder_activity = env['mail.activity'].search([
                ('res_model', '=', 'stock.picking'),
                ('res_id', '=', picking.id),
                ('activity_type_id', '=', backorder_activity_type.id),
                ('active', '=', True),
            ], limit=1)

            if not existing_backorder_activity:
                picking.activity_schedule(
                    'fmcg_business_automation.mail_activity_type_picking_backorder_required',
                    date_deadline=activity.date_deadline,
                    user_id=activity.user_id.id,
                    summary='Phiếu kho cần quyết định tạo Backorder',
                    note=(
                        'Phiếu kho %s chưa được hoàn tất vì còn số lượng cần '
                        'xử lý Backorder.' % picking.name
                    ),
                )

        elif isinstance(result, dict):
            raise UserError(
                'Phiếu kho %s cần xử lý wizard: %s'
                % (picking.name, result.get('res_model'))
            )

    elif picking and picking.state == 'confirmed':
            picking.activity_schedule(
                'fmcg_business_automation.mail_activity_type_picking_waiting',
                date_deadline=activity.date_deadline,
                user_id=activity.user_id.id,
                summary='Kiểm tra phiếu kho đang chờ',
                note=(
                    'Phiếu kho %s đang ở trạng thái chờ xử lý do còn '
                    'phụ thuộc nghiệp vụ.' % picking.name
                ),
            )

    elif picking and picking.state in ['draft']:
        env.ref(
            'fmcg_business_automation.action_schedule_picking_draft'
        ).with_context(
            active_model='stock.picking',
            active_id=picking.id,
            active_ids=picking.ids,
        ).run()

    else:
        raise UserError(
            'Picking %s không ở trạng thái hợp lệ (state: %s).'
            % (
                picking.name if picking else activity.res_id,
                picking.state if picking else 'not found',
            )
        )
